using FluentAssertions;
using UnitTests;
using UnitTests.Parser.Walkthroughs;
using Planetfall.Tests.Walkthrough;

namespace Planetfall.Tests.Parser;

/// <summary>
///     The sentences Planetfall's walkthroughs type that change the game, kept in
///     <c>UnitTests/Parser/Walkthroughs/walkthrough.planetfall.json</c> and checked at every parser layer as
///     part of the parser corpus. The file is not written by hand: it is what the game answers when each
///     walkthrough is replayed (see <see cref="WalkthroughHarvest" />), regenerated by the explicit test
///     below.
/// </summary>
[TestFixture]
public class WalkthroughInteractionTests
{
    private const string FileName = "walkthrough.planetfall.json";

    [Test]
    public void EverySentenceInTheFile_IsStillTypedByAWalkthrough()
    {
        var typed = DeterministicParserCoverage.AllWalkthroughInput(typeof(WalkthroughTestBase));

        WalkthroughHarvest.Load(FileName)
            .Select(interaction => interaction.Input).Where(input => !typed.Contains(input))
            .Should().BeEmpty("a sentence no walkthrough types any more has no game behind it - regenerate " +
                              "the file with RegenerateTheWalkthroughInteractions");
    }

    [Test]
    [Explicit("Rewrites walkthrough.planetfall.json by replaying every walkthrough - several minutes")]
    public async Task RegenerateTheWalkthroughInteractions()
    {
        var harvest = new WalkthroughHarvest("Planetfall");

        await harvest.Replay(typeof(WalkthroughTestBase), TestContext.Progress.WriteLine);

        WalkthroughHarvest.Save(WalkthroughHarvest.PathFor(FileName), harvest.Found);

        TestContext.Out.WriteLine($"{harvest.Found.Count} interactions");
        foreach (var (what, count) in harvest.Summary)
            TestContext.Out.WriteLine($"  {count,5} {what}");
        foreach (var sentence in harvest.NotReproducible)
            TestContext.Out.WriteLine($"NOT REPRODUCIBLE: {sentence}");
        foreach (var disagreement in harvest.GrammarDisagreements)
            TestContext.Out.WriteLine($"GRAMMAR: {disagreement}");
    }
}
